    const kanji = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.62), kanjiMat);
    kanji.position.set(0, 3.7, 0.07);
    g.add(kanji);
    g.traverse((o) => { if (o.isMesh) o.castShadow = true; });
