    g.add(hearth);
    const fireMat = new THREE.MeshStandardMaterial({ color: 0xff7b25, emissive: 0xff5a10, emissiveIntensity: 2.0, roughness: 0.8 });
    const fire = new THREE.Mesh(new THREE.BoxGeometry(1.0, 0.25, 0.7), fireMat);
