    // hood
    const hood = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 1.4, 2.4, 4), MAT.stone());
    hood.position.set(-1.2, 3.6, -2.1);
    g.add(hood);
    // anvil
    const anvilBase = new THREE.Mesh(new THREE.CylinderGeometry(0.38, 0.5, 0.5, 8), MAT.darkWood());
