417:     if (!check.ok) { this.toast(check.reason, 'warn'); this.sfx('error'); return null; }
418:     const s = this.state;
419:     const type = WEAPON_TYPES[typeId];
420:     for (const [k, n] of Object.entries(check.needs)) s.materials[k] -= n;
421:     const vals = Object.values(scores || {});
422:     const avg = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : 50;
423:     const assistant = (s.hires.assistant || 0) * 5;
424:     const workshopBonus = s.workshopLevel * 4 + (s.workshopLevel >= 3 ? 8 : 0);
425:     const quality = Math.round(clamp(avg * 0.63 + (MATERIALS[materialId]?.quality || 42) * 0.22 + assistant + workshopBonus + rand(-3, 3), 8, 100));
426:     const supernatural = !!type.supernatural;
427:     const legendary = supernatural && quality >= 82;
428:     const w = createWeapon(typeId, {
429:       name: name || craftName(legendary || supernatural),
430:       material: materialId,
431:       quality,
432:       durability: Math.round(70 + quality * 0.3),
433:       decoration,
434:       supernatural,
435:       legendary,
436:       forgedDay: s.day,
437:     });
438:     s.weapons.push(w);
439:     s.stats.crafted++;
440:     if (legendary) s.stats.legendaryCrafted++;
441:     this.addMoney(-(decoration ? 350 : 0));
442:     this.addRep(Math.max(2, Math.round(quality / 14)));
443:     this.log(`Forged ${w.name}, a ${type.name} of ${quality} quality.`);
444:     this.toast(`${w.name} is complete — quality ${quality}${legendary ? ' · LEGENDARY' : ''}.`, legendary ? 'good' : 'good');
445:     this.sfx(legendary ? 'success' : 'anvil');
446:     this.world?.rebuildWeaponRack();
447:     this.checkQuests();
448:     this.saveGame();
449:     this.ui?.refreshHUD();
450:     return w;
451:   }
