721:   makeOniStock() {
722:     const s = this.state;
723:     const pool = [
724:       { kind: 'seed', key: 'yomi', price: 3600, name: 'Ancient Yomi Maple Seed', jp: '幽玄の種', kanji: '幽', desc: 'A seed that is warm to the touch. Grows a maple from the far side of the mountain.' },
725:       { kind: 'seed', key: 'spiritPine', price: 4800, name: 'Spirit Pine Seed', jp: '霊松の種', kanji: '霊', desc: 'Needles of faint green light sleep inside this cone.' },
726:       { kind: 'material', key: 'onisteel', qty: 2, price: 5600, name: 'Enchanted Oni Steel ×2', jp: '鬼鉄', kanji: '鉄', desc: 'Two ingots of metal that drink candlelight.' },
727:       { kind: 'material', key: 'spiritwood', qty: 3, price: 5200, name: 'Spirit Wood ×3', jp: '霊木', kanji: '木', desc: 'Three lengths of wood that hum when bowed.' },
728:       { kind: 'material', key: 'folded', qty: 4, price: 2600, name: 'Folded Steel ×4', jp: '折鋼', kanji: '鋼', desc: 'A quiet stock of master-grade steel.' },
729:       { kind: 'tree', key: 'yomi', price: 12800, name: 'Yomi Maple Sapling', jp: '幽玄紅葉', kanji: '紅', desc: 'Already seven years shaped by a hand no one remembers. Pot-bound in black clay.' },
730:       { kind: 'tree', key: 'spiritPine', price: 14500, name: 'Spirit Pine Sapling', jp: '霊松', kanji: '松', desc: 'The tree breathes faintly. Its needles are cold.' },
731:       { kind: 'blueprint', price: 4600, name: 'Forbidden Blueprint', jp: '禁断の図', kanji: '禁', desc: 'A scroll of blackened skin. Unlocks a legendary design.' },
732:     ];
733:     const stock = [];
734:     const count = 4 + Math.floor(Math.random() * 2);
735:     const used = new Set();
736:     for (let i = 0; i < count; i++) {
737:       let entry;
738:       if (i === 1) {
739:         const avail = Object.keys(BLUEPRINTS).filter((b) => !s.blueprints.includes(b));
740:         const bp = avail.length ? pick(avail) : null;
741:         if (bp) entry = { kind: 'blueprint', key: bp, price: BLUEPRINTS[bp].price, name: BLUEPRINTS[bp].name, jp: '禁断', kanji: '禁', desc: BLUEPRINTS[bp].desc };
742:       }
743:       let guard = 0;
744:       while (!entry && guard++ < 30) {
745:         const e = pick(pool);
746:         if (e.kind === 'blueprint') continue;
747:         if (used.has(e.kind + e.key)) continue;
748:         entry = { ...e };
749:         used.add(e.kind + e.key);
750:       }
751:       if (!entry) entry = { ...pool[0], id: 'stock' + i };
752:       stock.push({ ...entry, id: 'stock_' + i + '_' + Math.random().toString(36).slice(2, 5), sold: false });
753:     }
754:     return stock;
755:   }
