813:   oniBid() {
814:     const lot = this.state.oniLot;
815:     if (!lot || lot.status !== 'open') return { ok: false };
816:     if (lot.item.kind === 'tree' && this.state.trees.length >= treeCapacity(this.state)) {
817:       this.toast('No room on your bonsai benches for the lot.', 'warn');
818:       return { ok: false };
819:     }
820:     const inc = Math.max(300, Math.round(lot.currentBid * 0.08 / 50) * 50);
821:     const next = lot.currentBid + inc;
822:     if (this.state.money < next) { this.toast('Not enough ryō to raise the bid.', 'warn'); this.sfx('error'); return { ok: false }; }
823:     lot.currentBid = next;
824:     lot.leader = 'you';
825:     lot.leaderName = 'You';
826:     lot.round++;
827:     lot.log.push({ who: 'you', text: `You raise to ${money(next)}.` });
828:     this.sfx('coin');
829:     const challengers = lot.rivals.filter((r) => r.max > next + 250);
830:     if (challengers.length && Math.random() < 0.8) {
831:       const rival = challengers[Math.floor(Math.random() * challengers.length)];
832:       const counter = Math.min(rival.max, next + Math.round((next * 0.06) / 50) * 50 + 150);
833:       lot.currentBid = counter;
834:       lot.leader = 'rival';
835:       lot.leaderName = rival.name;
836:       lot.log.push({ who: rival.name, text: `${rival.name} answers with ${money(counter)}.` });
837:       this.sfx('oni');
838:       return { ok: true, countered: true };
839:     }
840:     // win
841:     lot.status = 'won';
842:     lot.leader = 'you';
843:     lot.leaderName = 'You';
844:     this.addMoney(-lot.currentBid);
845:     const item = lot.item;
846:     if (item.kind === 'tree') this.state.trees.push(item);
