content.text:
24:html, body {
33:body { touch-action: none; }
35:canvas#scene { position: fixed; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
37:#app { position: fixed; inset: 0; }
239:.intro { position: fixed; inset: 0; z-index: 90; background: #100d0a; color: var(--paper); display: grid; place-items: center; overflow: hidden; transition: opacity 1s; }
240:.intro.gone { opacity: 0; pointer-events: none; }
241:.intro-bg {
248:.intro-bg::after {
252:.intro-vignette { position: absolute; inset: 0; box-shadow: inset 0 0 200px 60px #000; }
253:.intro-content { position: relative; z-index: 2; text-align: center; max-width: 760px; padding: 28px; animation: introin 1.4s ease; }
255:.intro-kanji { font-family: var(--jp); font-size: 15px; letter-spacing: .8em; color: var(--gold-soft); margin-bottom: 18px; opacity: .85; }
256:.intro-kicker { font-size: 11px; letter-spacing: .38em; color: #b7a68a; text-transform: uppercase; margin: 0 0 12px; }
257:.intro h1 { font-size: clamp(44px, 8vw, 88px); line-height: .88; margin: 0; font-weight: 500; letter-spacing: .07em; text-shadow: 0 4px 40px rgba(0,0,0,.6); }
258:.intro h1 em { font-style: italic; font-weight: 400; color: #e1c48d; letter-spacing: .03em; font-size: .82em; }
259:.intro-rule { display: flex; align-items: center; justify-content: center; gap: 16px; margin: 24px auto 20px; width: 70%; }
260:.intro-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(216,195,147,.55), transparent); }
261:.intro-rule i { font-family: var(--jp); font-style: normal; font-size: 17px; color: var(--verm-bright); width: 38px; height: 38px; border: 1px solid rgba(216,195,147,.4); display: grid; place-items: center; border-radius: 50%; }
262:.intro-copy { font-size: 16px; line-height: 1.7; color: #c8b99f; margin: 0 auto 30px; max-width: 600px; font-weight: 400; }
263:.intro-foot { display: flex; gap: 18px; justify-content: center; flex-wrap: wrap; margin-top: 30px; font-size: 10px; letter-spacing: .14em; color: #8d7f6a; text-transform: uppercase; }
264:.intro-foot span::before { content: '·'; margin-right: 8px; color: var(--gold); }
265:.intro-side {
334:.sheet-body { padding: 20px 26px 26px; overflow-y: auto; flex: 1 1 auto; z-index: 2; scrollbar-width: thin; scrollbar-color: #b5a17d transparent; }
