now_ms() { date +%s%3N; }
timed() {
  local label="$1"
  shift
  local began ended status
  began="$(now_ms)"
  set +e
  "$@"
  status=$?
  set -e
  ended="$(now_ms)"
  printf '[capture] [timing] %s: %d ms\n' "$label" "$((ended - began))"
  return "$status"
