import { createRequire } from 'node:module';
import { join } from 'node:path';
const home = process.env.HOME || '';
const runtime = join(home, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
console.log('boot', await page.evaluate(() => ({
  hasSamurai: !!window.SAMURAI,
  started: window.SAMURAI?.game?.started,
  trees: window.SAMURAI?.game?.state?.trees?.length,
  money: window.SAMURAI?.game?.state?.money,
})));
await page.click('#start-btn');
await page.waitForTimeout(1500);
for (const panel of ['bonsai', 'forge', 'auction', 'market', 'estate', 'map']) {
  await page.click(`#dock button[data-panel="${panel}"]`);
  await page.waitForTimeout(700);
  const info = await page.evaluate(() => {
    const ov = document.querySelector('.overlay');
    return { open: !!ov, text: ov?.innerText?.slice(0, 260), cards: ov?.querySelectorAll('.card').length };
  });
  console.log(panel, JSON.stringify(info));
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
}
console.log('errors', errors);
await page.screenshot({ path: '/tmp/opencode/probe.png' });
await browser.close();

