console.log('move', before, '->', after);

// water first tree via panel
await page.click('#dock button[data-panel="bonsai"]');
await page.waitForTimeout(600);
const watered = await page.evaluate(() => {
  const btn = [...document.querySelectorAll('[data-act]')].find((b) => /water/i.test(b.innerText));
  if (btn) { btn.click(); return true; }
  return false;
});
await page.waitForTimeout(500);
console.log('waterClicked', watered, await page.evaluate(() => SAMURAI.game.state.stats.watered), 'focus', await page.evaluate(() => SAMURAI.game.state.focus));
