const craft = await page.evaluate(() => {
  const g = SAMURAI.game;
  g.state.materials.iron = 9; g.state.materials.charcoal = 9;
  return { ok: g.startForge?.('tanto', 'iron') ?? 'no startForge', weapons: g.state.weapons.length };
});
