  SAMURAI.world.travelTo('village');
  return { x: SAMURAI.world.player.position.x, z: SAMURAI.world.player.position.z };
});
console.log('travel', travel);
await page.waitForTimeout(1200);
console.log('errors', errors);
await page.screenshot({ path: '/tmp/opencode/probe2.png' });
await browser.close();

