  return { meshes, tris: Math.round(tris), calls: r.info.render.calls, rtris: r.info.render.triangles, fps: Math.round(frames / 2), pixelRatio: r.getPixelRatio(), size: r.getSize(new (w.camera.position.constructor)()) };
});
console.log(info);
