  padding: 20px; background: rgba(10, 8, 6, .72); backdrop-filter: blur(4px);
  animation: bootin .35s ease;
}
@keyframes bootin { from { opacity: 0; } }
.boot-card {
  width: min(460px, 100%); padding: 26px 24px 20px; text-align: center;
  background: linear-gradient(165deg, #221d16, #14110d);
  border: 1px solid rgba(216, 195, 147, .38); border-radius: 3px;
  box-shadow: var(--shadow); color: var(--paper);
}
.boot-card .boot-kanji {
  width: 42px; height: 42px; margin: 0 auto 14px; display: grid; place-items: center;
  border-radius: 50%; border: 1px solid rgba(216, 195, 147, .5);
  color: var(--verm-bright); font-family: var(--jp); font-size: 22px;
}
.boot-card h2 { margin: 0 0 10px; font-size: 21px; font-weight: 500; letter-spacing: .05em; }
.boot-card p { margin: 0 0 18px; font-size: 13.5px; line-height: 1.6; color: #c8b99f; overflow-wrap: anywhere; }
