.boot-card .btn-quiet { background: transparent; color: #c8b99f; border: 1px solid rgba(216,195,147,.32); }
.boot-card .boot-hint { display: block; margin-top: 16px; font-size: 10px; line-height: 1.5; letter-spacing: .08em; color: #8d7f6a; }
