      weapons.createWeaponUpright({ type: id, material: 'iron', quality: 60 }, { size: 2 });
    } catch (e) { bad.push('weapon ' + id + ': ' + e.message); }
  }
  for (const id of Object.keys(SPECIES)) {
    try {
      const b = bonsai.createBonsai({ sp: id, age: 3, style: 22, variant: 7, pot: 0, health: 80, water: 60 }, 'autumn');
