  const blessing = (() => { g.state.money = 5000; g.state.flags.blessingDay = 0; try { return g.templeBlessing(); } catch (e) { return 'ERR ' + e.message; } })();
  return { weapons: Object.keys(WEAPON_TYPES).length, species: Object.keys(SPECIES).length, mats: mats.length, pots, bad, gather, offers, blessing };
});
