  let y = 0.8;
  for (let i = 0; i < 5; i++) {
    const w = 7 - i * 0.9;
    const body = new THREE.Mesh(new THREE.BoxGeometry(w * 0.62, 1.5, w * 0.62), i % 2 ? MAT.vermilion() : new THREE.MeshStandardMaterial({ color: 0xd9ccb0, roughness: 0.9 }));
