import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3003/', { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(1200);

console.log('locations', await page.evaluate(() => Object.keys(window.SAMURAI.world.game.state.discovered)));
await page.evaluate(() => { window.SAMURAI.world.travelTo('shrine'); window.SAMURAI.game.state.money = 2000; });
await page.waitForTimeout(900);
const shrine = await page.evaluate(() => {
  const g = window.SAMURAI.game;
  const before = { money: g.state.money, rep: g.state.rep };
  const ok = g.foxOffering();
  return { ok, before, after: { money: g.state.money, rep: g.state.rep }, camera: window.SAMURAI.world.camera.position.toArray(), zone: window.SAMURAI.world.currentZone };
});
console.log('shrine', shrine);
await page.screenshot({ path: '/tmp/opencode/shrine.png' });

await page.evaluate(() => { window.SAMURAI.world.travelTo('quarry'); window.SAMURAI.game.state.gathered = {}; });
await page.waitForTimeout(900);
const quarry = await page.evaluate(() => {
  const g = window.SAMURAI.game;
  return { got: g.gatherNode('quarry'), zone: window.SAMURAI.world.currentZone, camera: window.SAMURAI.world.camera.position.toArray() };
});
console.log('quarry', quarry);
await page.screenshot({ path: '/tmp/opencode/quarry.png' });
console.log('world errors', errors.slice(0, 6));
await browser.close();

