import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(1200);
const info = await page.evaluate(() => ({
  locs: Object.values(window.SAMURAI.world.constructor.LOCATIONS || {}).length,
  worldLocs: window.SAMURAI.world.currentZone,
  notices: document.getElementById('boot-notice')?.innerText || null,
  errors: window.SAMURAI.boot.errors,
}));
console.log('boot', info);
// Open map and travel through the UI
await page.click('#dock button[data-panel="map"]');
await page.waitForTimeout(700);
const pins = await page.evaluate(() => [...document.querySelectorAll('[data-loc]')].map((e) => e.dataset.loc));
console.log('map pins', [...new Set(pins)]);
await page.evaluate(() => {
  const btn = [...document.querySelectorAll('.location-list [data-loc]')].find((b) => b.dataset.loc === 'shrine');
  btn?.click();
});
await page.waitForTimeout(1600);
console.log('after travel', await page.evaluate(() => ({ zone: window.SAMURAI.world.currentZone, x: window.SAMURAI.world.player.position.x, z: window.SAMURAI.world.player.position.z, panel: !!document.querySelector('.overlay') })));
// Night Oni market test
await page.evaluate(() => { const g = window.SAMURAI.game; g.state.minutes = 22 * 60; g.state.day += 1; g.state.rep = 500; });
await page.waitForTimeout(600);
console.log('oni', await page.evaluate(() => {
  const g = window.SAMURAI.game;
  try { g.openOni(); return { open: true, stock: g.state.oniStock.length, lot: !!g.state.oniLot }; }
  catch (e) { return { open: false, err: e.message }; }
}));
await page.waitForTimeout(700);
await page.screenshot({ path: '/tmp/opencode/oni.png' });
console.log('errors', errors.slice(0, 8));
await browser.close();

