import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const URL = 'http://127.0.0.1:3004/';
const browser = await chromium.launch({ headless: true, args: ['--disable-webgl', '--disable-3d-apis', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.goto(URL, { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(1500);

const boot = await page.evaluate(() => ({
  mode: window.SAMURAI.boot.mode,
  lite: !!window.SAMURAI.world.lite,
  notices: document.getElementById('boot-notice')?.innerText || null,
  errors: window.SAMURAI.boot.errors.map((e) => e.kind + ': ' + e.message.slice(0, 90)),
  canvasIs2d: (() => { try { return window.SAMURAI.world.ctx instanceof CanvasRenderingContext2D; } catch { return false; } })(),
}));
console.log('BOOT', JSON.stringify(boot, null, 2));

const before = await page.evaluate(() => ({ ...window.SAMURAI.world.player.position }));
await page.keyboard.down('w');
await page.waitForTimeout(700);
await page.keyboard.up('w');
const after = await page.evaluate(() => ({ ...window.SAMURAI.world.player.position }));
console.log('MOVE', before, '->', after);
await page.screenshot({ path: '/tmp/opencode/lite-estate.png' });

await page.click('#dock button[data-panel="map"]');
await page.waitForTimeout(600);
const pins = await page.evaluate(() => [...new Set([...document.querySelectorAll('[data-loc]')].map((e) => e.dataset.loc))]);
console.log('PINS', pins.join(','));
await page.evaluate(() => {
  const btn = [...document.querySelectorAll('.location-list [data-loc]')].find((b) => b.dataset.loc === 'shrine');
  btn?.click();
});
await page.waitForTimeout(1500);
console.log('TRAVEL', await page.evaluate(() => ({ zone: window.SAMURAI.world.currentZone, px: Math.round(window.SAMURAI.world.player.position.x), pz: Math.round(window.SAMURAI.world.player.position.z) })));
await page.screenshot({ path: '/tmp/opencode/lite-shrine.png' });

// walk to the offering spot and interact
await page.evaluate(() => { const w = window.SAMURAI.world; w.player.position.x = w.loc.x; w.player.position.z = w.loc.z - 3.2; });
await page.waitForTimeout(400);
console.log('PROMPT', await page.evaluate(() => ({ text: document.getElementById('prompt-text')?.textContent, hidden: document.getElementById('prompt')?.classList.contains('hidden') })));
await page.keyboard.press('e');
await page.waitForTimeout(500);

// open the bonsai panel: preview must degrade, panel must render
await page.click('#dock button[data-panel="bonsai"]');
await page.waitForTimeout(700);
console.log('BONSAI', await page.evaluate(() => ({
  sheet: !!document.querySelector('.overlay .sheet'),
  litePreview: !!document.querySelector('.preview-lite'),
  crash: !!document.querySelector('.empty'),
})));
await page.screenshot({ path: '/tmp/opencode/lite-bonsai.png' });
await page.keyboard.press('Escape');
await page.waitForTimeout(300);

// forge panel and auction panel smoke test
for (const name of ['forge', 'auction', 'market', 'estate', 'codex']) {
  await page.click(`#dock button[data-panel="${name}"]`);
  await page.waitForTimeout(450);
  const ok = await page.evaluate(() => !!document.querySelector('.overlay .sheet') && !document.querySelector('.empty'));
  console.log('PANEL', name, ok);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);
}

console.log('ERRORS', errors.slice(0, 8));
await browser.close();

