const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const URL = 'http://127.0.0.1:3004/';

const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });

// ---- 1. normal WebGL boot ----
const gl = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const glErr = [];
gl.on('pageerror', (e) => glErr.push('PAGEERROR ' + e.message));
gl.on('console', (m) => { if (m.type() === 'error') glErr.push('CONSOLE ' + m.text().slice(0, 120)); });
await gl.goto(URL, { waitUntil: 'networkidle' });
await gl.click('#start-btn');
await gl.waitForTimeout(1600);
console.log('WEBGL BOOT', await gl.evaluate(() => ({ mode: window.SAMURAI.boot.mode, lite: !!window.SAMURAI.world.lite, notice: document.getElementById('boot-notice')?.innerText || null })));
await gl.screenshot({ path: '/tmp/opencode/webgl-ok.png' });

// ---- 2. lose the context and confirm automatic fallback ----
await gl.evaluate(() => {
  const r = window.SAMURAI.world.renderer;
  const ext = r?.getContext()?.getExtension('WEBGL_lose_context');
  ext?.loseContext();
  return !!ext;
});
await gl.waitForTimeout(3800);
console.log('AFTER LOSS', await gl.evaluate(() => ({
  mode: window.SAMURAI.boot.mode,
  lite: !!window.SAMURAI.world.lite,
  uiWorld: window.SAMURAI.ui.world === window.SAMURAI.world,
  gameWorld: window.SAMURAI.game.world === window.SAMURAI.world,
  notice: document.getElementById('boot-notice')?.innerText || null,
})));
await gl.click('#dock button[data-panel="map"]');
await gl.waitForTimeout(700);
console.log('LOSS UI', await gl.evaluate(() => ({ sheet: !!document.querySelector('.overlay .sheet'), pins: document.querySelectorAll('[data-loc]').length })));
await gl.screenshot({ path: '/tmp/opencode/lite-after-loss.png' });
console.log('GL ERRORS', glErr.filter((e) => !/WebGL context|THREE.WebGLRenderer/.test(e)).slice(0, 5));
await gl.close();

// ---- 3. mobile, no WebGL ----
const ctx2 = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
});
const mob = await ctx2.newPage();
const mobErr = [];
mob.on('pageerror', (e) => mobErr.push('PAGEERROR ' + e.message));
await mob.goto(URL, { waitUntil: 'networkidle' });
await mob.tap('#start-btn');
await mob.waitForTimeout(1600);
console.log('MOBILE', await mob.evaluate(() => ({
  mode: window.SAMURAI.boot.mode, lite: !!window.SAMURAI.world.lite,
  joystick: !document.getElementById('joystick').classList.contains('hidden'),
  interact: !document.getElementById('mobile-interact').classList.contains('hidden'),
  canvas2d: window.SAMURAI.world.ctx instanceof CanvasRenderingContext2D,
})));
await mob.screenshot({ path: '/tmp/opencode/lite-mobile.png' });
// drag the joystick upward to walk
const joy = await mob.locator('#joystick').boundingBox();
if (joy) {
  await mob.touchscreen.tap(joy.x + joy.width / 2, joy.y + joy.height / 2);
  const cx = joy.x + joy.width / 2, cy = joy.y + joy.height / 2;
  await mob.evaluate(({ x, y }) => {
    const el = document.getElementById('joystick');
    const down = new PointerEvent('pointerdown', { pointerId: 11, clientX: x, clientY: y, bubbles: true });
    el.dispatchEvent(down);
    const move = new PointerEvent('pointermove', { pointerId: 11, clientX: x, clientY: y - 28, bubbles: true });
    el.dispatchEvent(move);
  }, { x: cx, y: cy });
  await mob.waitForTimeout(700);
  await mob.evaluate(() => {
    const el = document.getElementById('joystick');
    el.dispatchEvent(new PointerEvent('pointerup', { pointerId: 11, bubbles: true }));
  });
}
console.log('MOBILE MOVE', await mob.evaluate(() => ({ z: Math.round(window.SAMURAI.world.player.position.z * 10) / 10 })));
// open the map via WORLD dock on mobile
await mob.tap('#dock button[data-panel="map"]');
await mob.waitForTimeout(600);
console.log('MOBILE MAP', await mob.evaluate(() => ({ sheet: !!document.querySelector('.overlay .sheet'), pins: document.querySelectorAll('[data-loc]').length })));
