import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const URL = 'http://127.0.0.1:3010/';

const browser = await chromium.launch({ headless: true, args: ['--disable-webgl', '--disable-3d-apis', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1024, height: 768 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + e.message));
await page.goto(URL, { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(1800);
console.log('PROD LITE', await page.evaluate(() => ({
  mode: window.SAMURAI.boot.mode,
  lite: !!window.SAMURAI.world.lite,
  notice: document.getElementById('boot-notice')?.innerText || null,
  loadingGone: document.getElementById('loading')?.classList.contains('gone'),
  introGone: document.getElementById('intro')?.classList.contains('gone'),
})));
await page.screenshot({ path: '/tmp/opencode/prod-lite.png' });
await page.evaluate(() => window.SAMURAI.world.travelTo('quarry'));
await page.waitForTimeout(700);
console.log('PROD TRAVEL', await page.evaluate(() => ({ zone: window.SAMURAI.world.currentZone, spots: window.SAMURAI.world.interactions.map((i) => i.id) })));
console.log('PROD ERRORS', errs.slice(0, 4));
await browser.close();

