import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errs = [];
page.on('pageerror', (e) => errs.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errs.push('CONSOLE ' + m.text().slice(0, 150)); });
await page.goto('http://127.0.0.1:3012/', { waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(2000);
console.log('WEBGL', await page.evaluate(() => ({ mode: window.SAMURAI.boot.mode, lite: !!window.SAMURAI.world.lite, notice: document.getElementById('boot-notice')?.innerText || null, errors: window.SAMURAI.boot.errors.length })));
await page.screenshot({ path: '/tmp/opencode/webgl-perf.png' });
// travel to a few locations to ensure no crashes and decent fps
for (const loc of ['shrine', 'quarry', 'mine']) {
  await page.evaluate((l) => window.SAMURAI.world.travelTo(l), loc);
  await page.waitForTimeout(400);
}
console.log('TRAVEL OK', await page.evaluate(() => window.SAMURAI.world.currentZone));
console.log('ERRORS', errs.filter(e => !/THREE.WebGLRenderer/i.test(e)).slice(0, 5));
await browser.close();
