  reset() {
    this.noSave = true;
    clearSave();
    location.reload();
  }

  unlockInfo() {
    return {
      capacity: treeCapacity(this.state),
      beauty: beautyOf(this.state),
      wages: dailyWages(this.state),
      visitors: visitorIncome(this.state),
      rank: rankFor(this.state.rep),
      next: nextRank(this.state.rep),
