      <g transform="translate(${mx(92) + 12},${my(-88) - 22})" opacity="${night ? 1 : 0.35}">
        <circle r="8" fill="${night ? '#8f2438' : '#6b5a4a'}" stroke="${night ? '#e8c6a0' : '#a99a80'}" stroke-width="1"/>
