  document.body.appendChild(veil);
  this.audio.sfx('click');
  setTimeout(() => {
    this.game.advanceTime(hours, { save: true });
    veil.remove();
    this.showZone(this.world.currentZone ? LOCATIONS[this.world.currentZone] : LOCATIONS.estate);
