setupJoystick() {
  const joy = this.el.joystick;
  if (!joy) return;
  const stick = joy.querySelector('.stick');
  let active = null, cx = 0, cy = 0, radius = 40;
  const start = (e) => {
    active = e.pointerId;
    const r = joy.getBoundingClientRect();
    cx = r.left + r.width / 2;
    cy = r.top + r.height / 2;
    radius = r.width * 0.38;
    try { joy.setPointerCapture?.(e.pointerId); } catch { /* stale pointer */ }
    e.preventDefault();
  };
  const move = (e) => {
    if (active !== e.pointerId) return;
    let dx = (e.clientX - cx) / radius;
    let dy = (e.clientY - cy) / radius;
    const len = Math.hypot(dx, dy);
    if (len > 1) { dx /= len; dy /= len; }
    this.world.setJoystick(dx, dy);
    stick.style.transform = `translate(calc(-50% + ${dx * 28}px), calc(-50% + ${dy * 28}px))`;
    e.preventDefault();
  };
  const end = (e) => {
    if (active !== e.pointerId) return;
    active = null;
    this.world.setJoystick(0, 0);
    stick.style.transform = 'translate(-50%, -50%)';
  };
  joy.addEventListener('pointerdown', start);
  joy.addEventListener('pointermove', move);
  joy.addEventListener('pointerup', end);
  joy.addEventListener('pointercancel', end);
}

