    ctx.fillStyle = '#e3b78e';
    ctx.beginPath();
    ctx.arc(0, -50 * s, 6.5 * s, 0, TAU);
    ctx.fill();
    // kasa hat
    ctx.fillStyle = '#c8a972';
    ctx.beginPath();
    ctx.ellipse(0, -54 * s, 14 * s, 5 * s, 0, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.moveTo(-6 * s, -54 * s);
    ctx.lineTo(0, -62 * s);
    ctx.lineTo(6 * s, -54 * s);
    ctx.closePath();
    ctx.fill();
