+      leg.position.set(x, 2.6, z); tower.add(leg);
+    }
+    const deck = new THREE.Mesh(new THREE.BoxGeometry(5.2, 0.3, 5.2), MAT.darkWood());
+    deck.position.y = 5.2; tower.add(deck);
+    for (const sx of [-1, 1]) {
+      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.8, 5.0), MAT.darkWood());
+      rail.position.set(sx * 2.5, 5.7, 0); tower.add(rail);
+      const rail2 = new THREE.Mesh(new THREE.BoxGeometry(5.0, 0.8, 0.14), MAT.darkWood());
+      rail2.position.set(0, 5.7, sx * 2.5); tower.add(rail2);
+    }
+    const roof = new THREE.Mesh(this.roofGeometry(6, 6, 1.2, 0.7, 0.5), MAT.roof());
+    roof.position.y = 8.0; tower.add(roof);
+    const brazier = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.6, 0.8, 9), MAT.stone());
+    brazier.position.y = 5.75; tower.add(brazier);
+    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.62, 1.8, 7), new THREE.MeshStandardMaterial({
