```js
  panel_story() {
    const s = this.game.state;
    const story = s.story || {};
    const idx = story.chapter || 0;
    const chapter = STORY_CHAPTERS[idx];
    const doneAll = story.done?.length || 0;
    const total = MISSIONS.length;
    const chapterDone = chapter ? chapter.missions.filter(id=>story.done.includes(id)).length : 0;

    if (!chapter) {
      // epilogue
      return this.sheet({
        title: 'The Mountain’s Name', sub:'STORY COMPLETE · 山', seal:'終',
        body: `<div class="story-hero"><div class="story-seal">終</div><div>...`,
        footer: ...
      });
    }

    const introSeen = story.seen.includes(chapter.id);
    const missionCards = chapter.missions.map(id=>{
      const m = MISSIONS.find(x=>x.id===id);
      const done = story.done.includes(id);
      const p = missionProgress(m,s,story);
      const loc = LOCATIONS[m.location];
      return `<div class="story-mission ${done?'done':''}">
        <div class="story-mission-head"><span class="story-check">${done?'✓':'•'}</span><b>${esc(m.title)}</b>${done?'<span class="tag green">complete</span>':`<span class="tag gold">${loc?.name||''}</span>`}</div>
        <p>${esc(m.text)}</p>
        ${done ? `<div class="tiny muted">${esc(m.done)}</div>` : `<div class="tiny muted">${esc(m.hint)}</div>`}
        <div class="story-progress"><u style="width:${Math.round(p.current/p.need*100)}%"></u></div>
        <div class="row between mt6"><span class="tiny muted">${p.need>1?`${p.current} / ${p.need}`:'Not yet'}</span><span class="gold tiny">+${money(m.reward)}${m.rep?` · +${m.rep} rep`:''}</span></div>
        ${!done && loc ? `<button class="btn btn-xs btn-ghost mt6" data-act="travel" data-loc="${m.location}">Travel to ${esc(loc.name)}</button>` : ''}
      </div>`;
    }).join('');

    const timeline = STORY_CHAPTERS.map((c,i)=>{
      const state = story.chaptersDone.includes(c.id) ? 'done' : i===idx ? 'current' : i<idx ? 'done' : '';
      return `<div class="story-step ${state}"><span>${c.numeral}</span><b>${esc(c.title)}</b></div>`;
    }).join('');

    return this.sheet({
      title: chapter.title, sub:`CHAPTER ${chapter.numeral} · ${chapter.jp} · STORY & MISSIONS`, seal: chapter.kanji,
      body: `<div class="story-hero"><div class="story-seal">${chapter.numeral}</div><div class="story-text"><div class="tiny muted">${esc(chapter.jp)} · ${chapterDone}/${chapter.missions.length} missions</div><h3>${esc(chapter.title)}</h3><p>${esc(chapter.intro)}</p><div class="tiny">Reward for the chapter: <b class="gold">${money(chapter.reward)}</b>${chapter.rep?` · +${chapter.rep} rep`:''}</div></div></div>
        <div class="story-timeline">${timeline}</div>
        <div class="section-label">Missions</div>
        <div class="story-missions">${missionCards}</div>
        <div class="rule"></div>
        <div class="tiny muted">Story missions advance when their conditions are met. Your Trials in the Codex remain optional.</div>`,
      footer: `<div class="tiny muted grow">Missions complete ${doneAll} / ${total}.</div><button class="btn btn-ghost" data-act="goto" data-panel="map">Open the map</button><button class="btn" data-act="close">Return to the mountain</button>`,
    });
  }
