import { createRequire } from 'node:module';
import { join } from 'node:path';
const reqPath = join(process.env.HOME || '', '.local/share/omgithub-playwright');
const require = createRequire(join(reqPath, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--enable-gpu', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 960, height: 600 } });
const errs = [];
page.on('pageerror', e => errs.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error') errs.push('CONSOLE ' + m.text().slice(0, 160)); });
await page.goto('http://127.0.0.1:3031/', { waitUntil: 'networkidle' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'networkidle' });
await page.click('#start-btn');
await page.waitForTimeout(1900);
console.log('BOOT', JSON.stringify(await page.evaluate(() => ({
  mode: window.SAMURAI.boot.mode, errors: window.SAMURAI.boot.errors.length,
  panel: window.SAMURAI.ui.panel, missions: document.querySelectorAll('.story-mission').length,
  title: document.querySelector('.sheet-title h2')?.textContent, chapter: window.SAMURAI.game.state.story.chapter,
}))));
await page.screenshot({ path: '/tmp/opencode/final-story1.jpg', type: 'jpeg', quality: 82 });

// Complete chapter 1 and check the panel shows the outro + chapter 2
await page.evaluate(() => {
  const g = window.SAMURAI.game; const s = g.state;
  s.focus = 999;
  s.stats.watered = 3; s.stats.crafted = 1; s.stats.sold = 1;
  g.checkQuests();
  window.SAMURAI.ui.openPanel('story');
});
await page.waitForTimeout(600);
console.log('CH2', JSON.stringify(await page.evaluate(() => ({
  chapter: window.SAMURAI.game.state.story.chapter,
  outro: document.querySelector('.story-outro p')?.textContent?.slice(0, 60),
  title: document.querySelector('.sheet-title h2')?.textContent,
  missions: document.querySelectorAll('.story-mission').length,
  stepsDone: document.querySelectorAll('.story-step.done').length,
}))));
await page.screenshot({ path: '/tmp/opencode/final-story2.jpg', type: 'jpeg', quality: 82 });

// Persistence: reload and confirm chapter 2 survives.
await page.reload({ waitUntil: 'networkidle' });
await page.waitForTimeout(1600);
console.log('RELOAD', JSON.stringify(await page.evaluate(() => ({
  chapter: window.SAMURAI.game.state.story.chapter,
  done: window.SAMURAI.game.state.story.done.length,
  money: window.SAMURAI.game.state.money,
}))));

// Kiln arrival view
await page.evaluate(() => { const u = window.SAMURAI.ui; if (u.panel) u.closePanel(); window.SAMURAI.game.state.minutes = 12*60; window.SAMURAI.game.state.hour = 12; window.SAMURAI.world.setTime(0); window.SAMURAI.world.travelTo('kiln'); });
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/final-kiln.jpg', type: 'jpeg', quality: 82 });
await page.evaluate(() => { const g = window.SAMURAI.game; g.state.flags.ridgeBeacon = true; g.world.setBeacon(true); g.world.travelTo('ridge'); });
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/final-ridge.jpg', type: 'jpeg', quality: 82 });

// FPS sample at the ridge
const fps = await page.evaluate(() => new Promise((resolve) => {
  let frames = 0; const t0 = performance.now();
  const tick = () => { frames++; if (performance.now() - t0 < 1600) requestAnimationFrame(tick); else resolve({ fps: Math.round(frames / ((performance.now() - t0) / 1000)), calls: window.SAMURAI.world.renderer.info.render.calls, tris: window.SAMURAI.world.renderer.info.render.triangles, ratio: window.SAMURAI.world.renderer.getPixelRatio() }); };
  requestAnimationFrame(tick);
}));
console.log('PERF', JSON.stringify(fps));
console.log('ERRORS', JSON.stringify(errs.slice(0, 6)));
await browser.close();
