buildSnowRidge() {
  const loc = LOCATIONS.ridge;
  const g = new THREE.Group();
  g.position.set(loc.x, 0, loc.z);
  this.scene.add(g);
  this.ridgeGroup = g;
  const snow = new THREE.MeshStandardMaterial({ color: 0xdfe8e9, roughness: 0.92, flatShading: true });
  const rock = new THREE.MeshStandardMaterial({ color: 0x6f7a7d, roughness: 1, flatShading: true });

  // snowy outcrops that frame the pass
  for (let i = 0; i < 10; i++) {
    const r = new THREE.Mesh(new THREE.DodecahedronGeometry(2 + Math.random() * 3, 0), i % 3 ? rock : snow);
    const side = i % 2 ? 1 : -1;
    r.position.set(side * (9 + Math.random() * 7), 0.8, -8 + Math.random() * 16);
    r.scale.set(1.1, 0.8 + Math.random() * 0.9, 1.1);
    r.rotation.set(Math.random(), Math.random(), Math.random());
    g.add(r);
    if (i % 2) {
      const cap = new THREE.Mesh(new THREE.SphereGeometry(0.8, 5, 4), snow);
      cap.position.set(r.position.x, 2.4 + Math.random(), r.position.z);
      cap.scale.set(1.5, 0.4, 1.5);
      g.add(cap);
    }
  }
  // stone stair
  for (let i = 0; i < 8; i++) {
    const step = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.18, 0.9), MAT.stone());
    step.position.set(0, 0.09 + i * 0.16, 11 - i * 0.95);
    g.add(step);
  }
  const torii = this.makeTorii(1.15, 0xa9362a, '峠');
  torii.position.set(0, 0, 12.5);
  g.add(torii);
  // watchtower and beacon
  const tower = new THREE.Group();
  for (const [x, z] of [[-1.9, -1.9], [1.9, -1.9], [-1.9, 1.9], [1.9, 1.9]]) {
    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.32, 5.2, 0.32), MAT.darkWood());
    leg.position.set(x, 2.6, z); tower.add(leg);
  }
  const deck = new THREE.Mesh(new THREE.BoxGeometry(5.2, 0.3, 5.2), MAT.darkWood());
  deck.position.y = 5.2; tower.add(deck);
  for (const sx of [-1, 1]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.8, 5.0), MAT.darkWood());
    rail.position.set(sx * 2.5, 5.7, 0); tower.add(rail);
    const rail2 = new THREE.Mesh(new THREE.BoxGeometry(5.0, 0.8, 0.14), MAT.darkWood());
    rail2.position.set(0, 5.7, sx * 2.5); tower.add(rail2);
  }
  const roof = new THREE.Mesh(this.roofGeometry(6, 6, 1.2, 0.7, 0.5), MAT.roof());
  roof.position.y = 8.0; tower.add(roof);
  const brazier = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.6, 0.8, 9), MAT.stone());
  brazier.position.y = 5.75; tower.add(brazier);
  const flame = new THREE.Mesh(new THREE.ConeGeometry(0.62, 1.8, 7), new THREE.MeshStandardMaterial({
    color: 0xffb75a, emissive: 0xff7a20, emissiveIntensity: 1.4, transparent: true, opacity: 0.9,
  }));
  flame.position.y = 6.9; tower.add(flame);
  const beaconLight = new THREE.PointLight(0xff9a4a, 0, 28, 2);
  beaconLight.position.y = 7.2; tower.add(beaconLight);
  this.beaconFlame = flame;
  this.beaconLight = beaconLight;
  tower.position.set(0, 0, -8.5);
  g.add(tower);
  this.registerCameraBlockers(tower);

  // prayer flags
  for (let i = 0; i < 7; i++) {
    const flag = new THREE.Mesh(new THREE.PlaneGeometry(0.45, 0.62), new THREE.MeshStandardMaterial({
      color: [0xd8d2c0, 0xb33a2b, 0x3f6d8a, 0xc9a45c][i % 4], roughness: 1, side: THREE.DoubleSide,
    }));
    flag.position.set(-6 + i * 2, 4.3 - Math.sin(i * 0.7) * 0.4, 6.5);
    flag.rotation.y = 0.2;
    g.add(flag);
  }
  for (const [x, z] of [[-6, 6], [6, 6]]) {
    const t = this.makeTree('pine', 1.15, this.season.id);
    t.position.set(x, 0, z);
    g.add(t);
    const l = this.makeStoneLantern(0.9, true);
    l.position.set(x * 0.65, 0, z + 3.5);
    g.add(l);
  }
  for (const [x, z, sc] of [[-13, 1, 0.9], [13, 2, 0.85], [-11, -12, 0.8], [12, -10, 0.95]]) {
    const t = this.makeTree('pine', sc, this.season.id);
    t.position.set(x, 0, z);
    g.add(t);
  }
  const sign = this.makeSign('雪 峠', 'SNOW RIDGE PASS');
  sign.position.set(4.5, 0, 9.2);
  sign.rotation.y = -0.2;
  g.add(sign);

  this.addInteraction({ id: 'ridge-beacon', label: 'Light the high beacon', kanji: '火', x: loc.x, z: loc.z - 8.5, y: 6.2, radius: 5.2 });
  this.addInteraction({ id: 'ridge-rest', label: 'Listen to the wind above the clouds', kanji: '風', x: loc.x + 6, z: loc.z + 4, y: 2.4, radius: 3.8 });
  this.setBeacon(!!this.game.state.flags?.ridgeBeacon);
}

setBeacon(lit) {
