        case 'rep400': done = s.rep >= 400; break;
        case 'masterpiece': done = s.stats.masterpieceSold > 0 || s.trees.some((t) => isMasterpiece(t)); break;
        case 'legendary': done = s.stats.legendaryCrafted > 0; break;
        default: break;
