    this.sfx('hammer');
  } else if (node === 'kiln') {
    give('mat', 'porcelain', 1 + Math.floor(Math.random() * 2));
    if (Math.random() < 0.55) give('mat', 'lacquer', 1);
    if (Math.random() < 0.4) give('mat', 'bronze', 1);
