  const dayF = clamp((Math.sin(((hour - 6) / 12) * Math.PI) + 0.1) / 1.1, 0, 1);
  const dusk = clamp(1 - Math.abs(hour - 18.2) / 2.6, 0, 1);
  const dawn = clamp(1 - Math.abs(hour - 6) / 2.4, 0, 1);
