import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const outDir = '/tmp/opencode/story-shots';
mkdirSync(outDir, { recursive: true });
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();

const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const consoleErrors = [];
page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()); });
page.on('pageerror', (err) => consoleErrors.push('pageerror: ' + err.message));

const log = (...a) => console.log(...a);
const results = {};

try {
  await page.goto('http://localhost:3002/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
  await page.waitForTimeout(1400);

  results.boot = await page.evaluate(() => ({
    mode: window.SAMURAI.boot.mode,
    ready: window.SAMURAI.boot.ready,
    errors: window.SAMURAI.boot.errors.slice(),
  }));
  log('BOOT', JSON.stringify(results.boot));

  // Close the automatic first-visit story sheet if it opened.
  await page.evaluate(() => {
    const close = document.querySelector('.sheet [data-act="close"]');
    if (close) close.click();
  });
  await page.waitForTimeout(250);

  // ————— Chapter I through real gameplay methods —————
  results.ch1 = await page.evaluate(() => {
    const g = window.SAMURAI.game;
    const s = g.state;
    const before = { chapter: s.story.chapter, money: s.money, rep: s.rep };
    let waters = 0;
    for (let pass = 0; pass < 3 && s.stats.watered < 3; pass++) {
      for (const t of s.trees) {
        if (s.stats.watered >= 3) break;
        if (t.water <= 93) {
          const r = g.careTree(t.id, 'water');
          if (r.ok) waters++;
        }
      }
    }
    const weapon = g.finishCraft({
      typeId: 'tanto', materialId: 'iron',
      scores: { heat: 82, hammer: 84, fold: 78, sharpen: 86, polish: 80 },
    });
    let sale = null;
    if (weapon) {
      sale = g.completeSale({
        item: weapon, currentBid: 2400, fee: 0.07, sold: true,
        winner: { type: 'samurai', name: 'A Test Buyer' },
      });
    }
    return {
      before, waters, crafted: !!weapon, sold: !!sale,
      chapter: s.story.chapter,
      done: [...s.story.done],
      chaptersDone: [...s.story.chaptersDone],
      after: { money: s.money, rep: s.rep },
      stats: { watered: s.stats.watered, crafted: s.stats.crafted, sold: s.stats.sold },
    };
  });
  log('CH1', JSON.stringify(results.ch1));

  // Story panel rendering.
  await page.click('#btn-story');
  await page.waitForTimeout(400);
  results.storyPanel = await page.evaluate(() => {
    const sheet = document.querySelector('.sheet');
    return {
      open: !!sheet,
      title: sheet?.querySelector('h2')?.textContent?.trim() || '',
      missions: [...document.querySelectorAll('.sheet .story-mission')].map((n) => n.innerText.replace(/\s+/g, ' ').trim()),
      steps: [...document.querySelectorAll('.sheet .story-step')].map((n) => n.innerText.replace(/\s+/g, ' ').trim()),
      body: sheet?.innerText?.slice(0, 300) || '',
    };
  });
  log('STORY PANEL', JSON.stringify(results.storyPanel));
  await page.screenshot({ path: `${outDir}/story-panel.png` });
  await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());
  await page.waitForTimeout(250);

  // ————— New locations in WebGL —————
  results.webglLocations = await page.evaluate(async () => {
    const { game, world } = window.SAMURAI;
    const out = {};
    for (const id of ['shrine', 'quarry', 'kiln', 'ridge']) {
      world.travelTo(id);
      await new Promise((r) => setTimeout(r, 120));
      const ints = world.interactions
        .filter((i) => Math.hypot(i.pos.x - world.player.position.x, i.pos.z - world.player.position.z) < 40)
        .map((i) => ({ id: i.id, d: +Math.hypot(i.pos.x - world.player.position.x, i.pos.z - world.player.position.z).toFixed(2) }));
      out[id] = {
        player: [world.player.position.x, world.player.position.z],
        zone: world.currentZone,
        interactions: ints,
      };
    }
    const loc = { x: world.player.position.x, z: world.player.position.z };
    out.ridgeGroup = world.ridgeGroup ? { children: world.ridgeGroup.children.length, pos: [world.ridgeGroup.position.x, world.ridgeGroup.position.z] } : null;
    out.beacon = world.beaconFlame ? { visible: world.beaconFlame.visible } : null;
    return out;
  });
  log('WEBGL LOCATIONS', JSON.stringify(results.webglLocations));

  // Screenshot the ridge from its spawn.
  await page.evaluate(() => window.SAMURAI.world.travelTo('ridge'));
  await page.waitForTimeout(700);
  await page.screenshot({ path: `${outDir}/ridge-webgl.png` });

  // Walk to the beacon and light it.
  results.beacon = await page.evaluate(() => {
    const { game, world } = window.SAMURAI;
    world.travelTo('ridge');
    world.player.position.set(0, 0, -228.5);
    world.updateInteractions();
    const nearby = world.nearby?.id || null;
    const ok = game.worldAction('ridge-beacon');
    return {
      nearby,
      ok,
      ridgeBeacons: game.state.stats.ridgeBeacons,
      flame: !!world.beaconFlame?.visible,
      light: world.beaconLight?.intensity || 0,
    };
  });
  log('BEACON', JSON.stringify(results.beacon));
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${outDir}/ridge-beacon-webgl.png` });

  // Shrine offering + quarry + kiln gathers at the real interaction points.
  results.actions = await page.evaluate(async () => {
    const { game, world } = window.SAMURAI;
    const step = async (locId, x, z, action) => {
      world.travelTo(locId);
      world.player.position.set(x, 0, z);
      world.updateInteractions();
      const nearby = world.nearby?.id || null;
      const result = game.worldAction(action);
      return { nearby, result };
    };
    const before = { shrine: game.state.stats.shrineOfferings, silver: game.state.materials.silver, kiln: game.state.stats.gathered_kiln };
    const shrine = await step('shrine', -46, -131.4, 'shrine-offer');
    const quarry = await step('quarry', -172, -36.5, 'quarry-gather');
    const kiln = await step('kiln', -142, 129.5, 'kiln-gather');
    return {
      shrine, quarry, kiln,
      after: {
        shrine: game.state.stats.shrineOfferings,
        silver: game.state.materials.silver,
        quarry: game.state.stats.gathered_quarry,
        kiln: game.state.stats.gathered_kiln,
        wood: game.state.materials.keyaki,
      },
      before,
      storyDone: [...game.state.story.done],
    };
  });
  log('ACTIONS', JSON.stringify(results.actions));

  // ————— 2D fallback —————
  results.lite = await page.evaluate(async () => {
    const ok = window.SAMURAI.useLiteView('validation');
    await new Promise((r) => setTimeout(r, 300));
    const { world, boot } = window.SAMURAI;
    const out = { switched: ok, mode: boot.mode, lite: !!world.lite, locations: {} };
    for (const id of ['shrine', 'quarry', 'kiln', 'ridge']) {
      world.travelTo(id);
      out.locations[id] = {
        player: [world.player.position.x, world.player.position.z],
        interactions: world.interactions.map((i) => i.id),
        spots: (world.interactions || []).length,
      };
    }
    world.travelTo('ridge');
    return out;
  });
  log('LITE', JSON.stringify(results.lite));
  await page.waitForTimeout(700);
  await page.screenshot({ path: `${outDir}/ridge-2d.png` });

  // ————— Mission wiring for chapters II–V —————
  results.chapters = await page.evaluate(() => {
    const { game } = window.SAMURAI;
    const s = game.state;
    const snap = () => ({
      chapter: s.story.chapter,
      done: [...s.story.done],
      chaptersDone: [...s.story.chaptersDone],
      money: s.money,
      rep: s.rep,
    });
    const out = { start: snap() };

    // Chapter II.
    s.story.chapter = 1;
    s.stats.gathered_quarry = 1;
    s.materials.silver = Math.max(2, s.materials.silver || 0);
    s.stats.commissionsDone = 1;
    game.checkStory();
    out.ch2 = snap();

    // Chapter III.
    s.stats.shrineOfferings = 1;
    s.stats.gathered_kiln = 1;
    s.stats.ornaments = 1;
    game.checkStory();
    out.ch3 = snap();

    // Chapter IV.
    s.stats.oniVisits = 1;
    s.stats.oniBuys = 1;
    s.stats.legendaryCrafted = 1;
    game.checkStory();
    out.ch4 = snap();

    // Chapter V: satisfy four sub-goals, then final.
    s.stats.ridgeBeacons = 1;
    s.rep = 400;
    const tree = s.trees[0];
    if (tree) {
      tree.age = Math.max(5, tree.age);
      tree.style = Math.max(82, tree.style);
      tree.health = Math.max(60, tree.health);
      tree.heirloom = true;
    }
    game.checkStory();
    out.ch5 = snap();

    const before = s.money;
    game.checkStory();
    out.idempotent = { before, after: s.money, same: before === s.money };

    const chapter5 = { num: 5, out: game.currentStoryChapter() };
    return { ...out, chapter5 };
  });
  log('CHAPTERS', JSON.stringify(results.chapters));

  // Story-complete UI + map highlights after progression.
  await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());
  await page.click('#btn-story');
  await page.waitForTimeout(350);
  results.completePanel = await page.evaluate(() => ({
    text: document.querySelector('.sheet')?.innerText?.replace(/\s+/g, ' ').slice(0, 350) || '',
  }));
  await page.screenshot({ path: `${outDir}/story-complete.png` });

  // Map with mission highlights / all locations.
  await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());
  await page.waitForTimeout(150);
  await page.click('#btn-map');
  await page.waitForTimeout(350);
  results.map = await page.evaluate(() => ({
    pins: [...document.querySelectorAll('.sheet .map-pin')].length,
    names: [...document.querySelectorAll('.sheet .map-pin')].map((n) => n.getAttribute('data-loc')),
  }));
  await page.screenshot({ path: `${outDir}/map.png` });

  results.consoleErrors = consoleErrors;
  log('CONSOLE ERRORS', JSON.stringify(consoleErrors));
  log('RESULT', JSON.stringify(results, null, 2));
} finally {
  await browser.close();
}

