import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
const out = {};

await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.click('#start-btn');
await page.waitForTimeout(1200);
await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());

out.afterActions = await page.evaluate(() => {
  const g = window.SAMURAI.game;
  const s = g.state;
  for (let i = 0; i < 3; i++) {
    const t = s.trees.find((x) => x.water <= 93);
    if (t) g.careTree(t.id, 'water');
  }
  const w = g.finishCraft({ typeId: 'tanto', materialId: 'iron', scores: { heat: 80, hammer: 80, fold: 80, sharpen: 80, polish: 80 } });
  g.completeSale({ item: w, currentBid: 2400, fee: 0.07, sold: true, winner: { type: 'samurai', name: 'Persistence Buyer' } });
  g.saveGame();
  return { chapter: s.story.chapter, done: [...s.story.done], chaptersDone: [...s.story.chaptersDone], money: s.money, rep: s.rep };
});

await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.click('#start-btn');
await page.waitForTimeout(1200);
out.afterReload = await page.evaluate(() => {
  const s = window.SAMURAI.game.state;
  return { chapter: s.story.chapter, done: [...s.story.done], chaptersDone: [...s.story.chaptersDone], money: s.money, rep: s.rep };
});

// Simulate a pre-story save: keep most state but remove story/new stats.
out.legacy = await page.evaluate(async () => {
  const raw = JSON.parse(localStorage.getItem('way-of-the-samurai-v1'));
  delete raw.story;
  delete raw.stats.commissionsDone;
  delete raw.stats.shrineOfferings;
  delete raw.stats.ridgeBeacons;
  raw.materials = { iron: 4, charcoal: 6 };
  localStorage.setItem('way-of-the-samurai-v1', JSON.stringify(raw));
  return { hadStory: !!raw.story };
});
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.waitForTimeout(600);
out.afterLegacy = await page.evaluate(() => {
  const { game, boot } = window.SAMURAI;
  const s = game.state;
  return {
    bootErrors: boot.errors,
    story: s.story,
    stats: { commissionsDone: s.stats.commissionsDone, shrineOfferings: s.stats.shrineOfferings, ridgeBeacons: s.stats.ridgeBeacons },
    hasSilver: Object.prototype.hasOwnProperty.call(s.materials, 'silver'),
    chapter: game.currentStoryChapter()?.id || null,
  };
});

out.errors = errors;
console.log(JSON.stringify(out, null, 2));
await browser.close();

