.story-missions { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 9px; }
.story-mission { border: 1px solid rgba(80, 60, 35, .24); background: rgba(255, 250, 236, .42); padding: 10px 12px; }
.story-mission.done { opacity: .72; border-color: rgba(90, 110, 70, .45); }
.story-mission-head { display: flex; align-items: center; gap: 7px; }
.story-mission-head b { flex: 1; font-size: 13px; font-weight: 600; }
.story-check {
  width: 15px; height: 15px; display: grid; place-items: center; flex: 0 0 auto;
  border: 1px solid rgba(80, 60, 35, .4); color: var(--verm); font-size: 10px;
}
.story-mission.done .story-check { background: var(--moss); border-color: var(--moss); color: #fff; }
.story-mission p { margin: 6px 0 4px; font-size: 12.5px; line-height: 1.45; color: #4e4436; }
.story-progress { height: 3px; margin-top: 7px; background: rgba(80, 60, 35, .16); overflow: hidden; }
.story-progress u { display: block; height: 100%; background: linear-gradient(90deg, var(--gold), var(--verm)); transition: width .3s; }
.map-pin { cursor: pointer; }
.map-pin:hover circle { fill: #b33a2b !important; }
.map-wrap .hero-label { pointer-events: none; }
@media (max-width: 700px) {
  .offline-pill { display: none; }
  .big-amount { font-size: 42px; }
  .sheet-head .sheet-title h2 { font-size: 18px; }
  .map-wrap { height: 240px; }
}

/* ————— boot / graphics failure notice ————— */
.boot-notice {
  position: fixed; inset: 0; z-index: 120; display: grid; place-items: center;
  padding: 20px; background: rgba(10, 8, 6, .72); backdrop-filter: blur(4px);
  animation: bootin .35s ease;
}
@keyframes bootin { from { opacity: 0; } }
.boot-card {
  width: min(460px, 100%); padding: 26px 24px 20px; text-align: center;
  background: linear-gradient(165deg, #221d16, #14110d);
  border: 1px solid rgba(216, 195, 147, .38); border-radius: 3px;
