import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
mkdirSync('/tmp/opencode/story-shots', { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.tap('#start-btn');
await page.waitForTimeout(1500);
await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());
await page.tap('#btn-story');
await page.waitForTimeout(400);
const story = await page.evaluate(() => {
  const sheet = document.querySelector('.sheet');
  const r = sheet?.getBoundingClientRect();
  return {
    open: !!sheet,
    width: Math.round(r?.width || 0),
    viewport: window.innerWidth,
    overflow: document.documentElement.scrollWidth - window.innerWidth,
    missions: document.querySelectorAll('.sheet .story-mission').length,
    title: sheet?.querySelector('h2')?.textContent?.trim() || '',
  };
});
await page.screenshot({ path: '/tmp/opencode/story-shots/mobile-story.png' });
await page.evaluate(() => document.querySelector('.sheet [data-act="close"]')?.click());
await page.waitForTimeout(200);
await page.evaluate(() => window.SAMURAI.world.travelTo('ridge'));
await page.waitForTimeout(1200);
const ridge = await page.evaluate(() => ({
  zone: window.SAMURAI.world.currentZone,
  dockVisible: !!document.querySelector('#dock'),
  promptHidden: document.querySelector('#prompt')?.classList.contains('hidden'),
}));
await page.screenshot({ path: '/tmp/opencode/story-shots/mobile-ridge.png' });
console.log(JSON.stringify({ story, ridge, errors }, null, 2));
await browser.close();

