import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.click('#start-btn');
await page.waitForTimeout(1400);
await page.evaluate(() => {
  const ui = window.SAMURAI.ui;
  if (ui.panel) ui.closePanel();
  window.SAMURAI.game.addMoney(40000);
});

const webglPanels = await page.evaluate(async () => {
  const ui = window.SAMURAI.ui;
  const out = {};
  for (const name of ['bonsai', 'forge', 'auction', 'market', 'estate', 'codex', 'map', 'temple', 'story']) {
    ui.openPanel(name);
    await new Promise((r) => setTimeout(r, 60));
    out[name] = {
      sheet: !!document.querySelector('.sheet'),
      title: document.querySelector('.sheet h2')?.textContent?.trim() || '',
      actions: document.querySelectorAll('.sheet [data-act]').length,
    };
    ui.closePanel();
  }
  return out;
});

const actions = await page.evaluate(() => {
  const { game, world } = window.SAMURAI;
  const s = game.state;
  game.focus(999);
  const tree = s.trees[0];
  const prune = game.careTree(tree.id, 'prune');
  const wire = game.careTree(tree.id, 'wire');
  game.focus(999);
  const water = game.careTree(tree.id, 'water');
  const seed = game.buySeed('maple');
  const mat = game.buyMaterial('charcoal', 1);
  const garden = game.upgrade('garden');
  const temple = game.templeBlessing();
  world.travelTo('shrine');
  const offering = game.foxOffering();
  world.travelTo('ridge');
  const beacon = game.lightBeacon();
  s.minutes = 20 * 60;
  s.hour = 20;
  world.travelTo('bamboo');
  const oni = game.openOni();
  const stock = s.oniStock.map((e) => ({ name: e.name, price: e.price, kind: e.kind }));
  const bought = s.oniStock[0] ? game.buyOni(s.oniStock[0].id) : null;
  game.ui.closePanel();
  return {
    prune, wire, water, seed, mat, garden, temple, offering, beacon, oni, bought, stock,
    stats: s.stats,
    money: s.money,
    story: ...(s.story ? { chapter: s.story.chapter, done: [...s.story.done] } : { chapter: null }),
  };
});

await page.evaluate(() => window.SAMURAI.useLiteView('smoke'));
await page.waitForTimeout(400);
const litePanels = await page.evaluate(async () => {
  const ui = window.SAMURAI.ui;
  const out = {};
  for (const name of ['bonsai', 'forge', 'auction', 'market', 'estate', 'codex', 'map', 'temple', 'story']) {
    ui.openPanel(name);
    await new Promise((r) => setTimeout(r, 50));
    out[name] = !!document.querySelector('.sheet');
    ui.closePanel();
  }
  for (const id of ['estate', 'shrine', 'quarry', 'kiln', 'ridge']) window.SAMURAI.world.travelTo(id);
  return { panels: out, mode: window.SAMURAI.boot.mode, lite: !!window.SAMURAI.world.lite };
});

console.log(JSON.stringify({ webglPanels, actions, litePanels, errors }, null, 2));
await browser.close();

