import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.click('#start-btn');
await page.waitForTimeout(1600);

const auto = await page.evaluate(() => ({ panel: window.SAMURAI.ui.panel, chapter: window.SAMURAI.game.currentStoryChapter()?.id }));
// Use the story mission's travel button (Chapter I first mission -> estate).
await page.click('.sheet .story-mission [data-act="travel"]');
await page.waitForTimeout(1200);
const afterStoryTravel = await page.evaluate(() => ({
  panel: window.SAMURAI.ui.panel,
  player: [window.SAMURAI.world.player.position.x, window.SAMURAI.world.player.position.z],
  zone: window.SAMURAI.world.currentZone,
  discovered: [...window.SAMURAI.game.state.discovered],
}));

// Open map and travel to the quarry via its pin.
await page.click('#btn-map');
await page.waitForTimeout(400);
const mapMarked = await page.evaluate(() => ({
  missionPins: [...document.querySelectorAll('.sheet .map-pin circle[stroke="#b33a2b"]')].length,
  quarryPin: !!document.querySelector('.sheet .map-pin[data-loc="quarry"]'),
  locationTags: [...document.querySelectorAll('.sheet .location .tag')].map((n) => n.textContent.trim()),
}));
await page.click('.sheet .map-pin[data-loc="quarry"]');
await page.waitForTimeout(1400);
const afterMapTravel = await page.evaluate(() => ({
  panel: window.SAMURAI.ui.panel,
  player: [window.SAMURAI.world.player.position.x, window.SAMURAI.world.player.position.z],
  zone: window.SAMURAI.world.currentZone,
  discovered: [...window.SAMURAI.game.state.discovered],
}));
console.log(JSON.stringify({ auto, afterStoryTravel, mapMarked, afterMapTravel, errors }, null, 2));
await browser.close();

