import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync('/home/runner/.local/share/omgithub-playwright/linux.json', 'utf8'));
if (!process.env.DISPLAY) process.env.DISPLAY = ':' + readFileSync('/home/runner/.local/share/omgithub-playwright/display', 'utf8').trim();
mkdirSync('/tmp/opencode/story-shots', { recursive: true });
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.waitForFunction(() => window.SAMURAI?.boot?.ready, null, { timeout: 45000 });
await page.click('#start-btn');
await page.waitForTimeout(1200);
await page.evaluate(() => {
  document.querySelector('.sheet [data-act="close"]')?.click();
  window.SAMURAI.world.travelTo('ridge');
});
await page.waitForTimeout(900);

const walk = await page.evaluate(async () => {
  const { world, game } = window.SAMURAI;
  world.clickTarget = world.player.position.clone().set(0, 0, -229.5);
  const t0 = performance.now();
  while (performance.now() - t0 < 25000) {
    await new Promise((r) => setTimeout(r, 100));
    if (world.nearby?.id === 'ridge-beacon') break;
  }
  return {
    pos: [world.player.position.x, world.player.position.z],
    nearby: world.nearby?.id || null,
    beacons: game.state.stats.ridgeBeacons,
    ms: Math.round(performance.now() - t0),
  };
});
console.log('WALK', JSON.stringify(walk));
await page.screenshot({ path: '/tmp/opencode/story-shots/ridge-approach.png' });

const point = await page.evaluate(() => {
  const { world } = window.SAMURAI;
  const cam = world.camera;
  const v = world.player.position.clone();
  // screen position of the beacon interaction object
  const inter = world.interactions.find((i) => i.id === 'ridge-beacon');
  const p = inter.pos.clone();
  p.y = 2.4;
  p.project(cam);
  return {
    x: Math.round((p.x * 0.5 + 0.5) * window.innerWidth),
    y: Math.round((-p.y * 0.5 + 0.5) * window.innerHeight),
    z: p.z,
  };
});
console.log('SCREEN', JSON.stringify(point));
await page.mouse.click(point.x, point.y);
await page.waitForTimeout(900);
const after = await page.evaluate(() => ({
  beacons: window.SAMURAI.game.state.stats.ridgeBeacons,
  flame: !!window.SAMURAI.world.beaconFlame?.visible,
  light: window.SAMURAI.world.beaconLight?.intensity || 0,
  nearby: window.SAMURAI.world.nearby?.id || null,
  toasts: [...document.querySelectorAll('.toast')].map((t) => t.innerText.replace(/\s+/g, ' ').trim()),
}));
console.log('AFTER', JSON.stringify(after));
await page.screenshot({ path: '/tmp/opencode/story-shots/ridge-beacon-clicked.png' });
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

