91: function palette(seasonId, hour, weather) {
92:   const pal = PALETTES[seasonId] || PALETTES.spring;
93:   const dayF = clamp((Math.sin(((hour - 6) / 12) * Math.PI) + 0.1) / 1.1, 0, 1);
94:   const dusk = clamp(1 - Math.abs(hour - 18.2) / 2.6, 0, 1);
95:   const dawn = clamp(1 - Math.abs(hour - 6) / 2.4, 0, 1);
96:   const night = 1 - dayF;
97:   const weatherDark = weather === 'storm' ? 0.35 : weather === 'rain' ? 0.2 : 0;
98: 
99:   let top = mix(hexToRgb(0x0a1224), hexToRgb(pal.top), dayF);
100:   let bottom = mix(hexToRgb(0x202b3d), hexToRgb(pal.bottom), dayF);
101:   top = mix(top, hexToRgb(0x495a78), Math.max(dawn, dusk) * 0.55);
102:   bottom = mix(bottom, hexToRgb(0xe79f72), Math.max(dawn, dusk) * 0.45);
103:   top = mix(top, hexToRgb(0x2c3038), weatherDark * 0.7);
104:   bottom = mix(bottom, hexToRgb(0x4a4c44), weatherDark * 0.6);
105: 
106:   const ground = mix(hexToRgb(0x1c2422), hexToRgb(pal.ground), dayF);
107:   const far = mix(hexToRgb(0x121a20), hexToRgb(pal.far), dayF);
108:   const mount = mix(hexToRgb(0x0e151c), hexToRgb(pal.mount), dayF);
109:   const leaf = mix(hexToRgb(0x1a2418), hexToRgb(pal.leaf), dayF);
110:   const accent = mix(hexToRgb(0x4b3a34), hexToRgb(pal.accent), dayF);
111:   return {
112:     dayF, night, top, bottom, ground, far, mount, leaf, accent,
113:     isNight: isNight(hour),
114:     sunX: clamp((hour - 6) / 12, 0, 1),
115:   };
116: }
