375: export function missionProgress(mission, state, story) {
376:   const g = mission?.goal || {};
377:   const need = Math.max(1, g.need ?? 1);
378:   let current = 0;
379:   switch (g.type) {
380:     case 'stat': current = Number(state.stats?.[g.key] || 0); break;
381:     case 'gathered': current = Number(state.stats?.[`gathered_${g.key}`] || 0); break;
382:     case 'material': current = Number(state.materials?.[g.key] || 0); break;
383:     case 'rep': current = Number(state.rep || 0); break;
384:     case 'masterpiece': current = (state.stats?.masterpieceSold > 0 || (state.trees || []).some((t) => isMasterpiece(t))) ? 1 : 0; break;
385:     case 'heirloom': current = (state.trees || []).some((t) => t.heirloom) ? 1 : 0; break;
386:     case 'flag': current = state.flags?.[g.key] ? 1 : 0; break;
387:     case 'storyDone': current = (g.ids || []).filter((id) => story?.done?.includes(id)).length; break;
388:     default: current = 0;
389:   }
390:   return { current: Math.min(current, need), need, done: current >= need };
391: }
