413: export function storyMissionsLeft(state) {
414:   const story = state.story || {};
415:   const chapter = STORY_CHAPTERS[story.chapter || 0];
416:   if (!chapter) return [];
417:   return chapter.missions
418:     .map((id) => MISSIONS.find((m) => m.id === id))
419:     .filter((m) => m && !(story.done || []).includes(m.id));
420: }
