395: export function missionProgress(mission, state, story) {
396:   const g = mission?.goal || {};
397:   const need = Math.max(1, g.need ?? 1);
398:   let current = 0;
399:   switch (g.type) {
400:     case 'stat': current = Number(state.stats?.[g.key] || 0); break;
401:     case 'gathered': current = Number(state.stats?.[`gathered_${g.key}`] || 0); break;
402:     case 'material': current = Number(state.materials?.[g.key] || 0); break;
403:     case 'rep': current = Number(state.rep || 0); break;
404:     case 'masterpiece': current = (state.stats?.masterpieceSold > 0 || (state.trees || []).some((t) => isMasterpiece(t))) ? 1 : 0; break;
405:     case 'heirloom': current = (state.trees || []).some((t) => t.heirloom) ? 1 : 0; break;
406:     case 'flag': current = state.flags?.[g.key] ? 1 : 0; break;
407:     case 'storyDone': current = (g.ids || []).filter((id) => story?.done?.includes(id)).length; break;
408:     default: current = 0;
409:   }
410:   return { current: Math.min(current, need), need, done: current >= need };
411: }
