451: export function treeValue(t) {
452:   const sp = SPECIES[t.sp];
453:   if (!sp) return 0;
454:   const ageFactor = 1 + t.age * 0.55;
455:   const styleFactor = 0.4 + Math.pow(t.style / 100, 1.55) * 2.9;
456:   const healthFactor = 0.42 + (t.health / 100) * 0.68;
457:   const pot = POTS[t.pot] || POTS[0];
458:   const master = t.age >= 5 && t.style >= 82 && t.health >= 60 ? 2.0 : 1;
459:   const superM = sp.supernatural ? 3.4 : 1;
460:   const variantM = 1 + ((t.variant || 0) % 9 === 0 ? 0.18 : 0);
461:   const wiredM = t.wiring ? 1.08 : 1;
462:   return Math.round(sp.base * ageFactor * styleFactor * healthFactor * pot.mult * master * superM * variantM * wiredM / 10) * 10;
463: }
