node --input-type=module <<'EOF'
globalThis.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };
const { Game } = await import('./src/game.js');
const { STORY_CHAPTERS, MISSIONS, locationStoryAccess } = await import('./src/data.js');
const game = new Game();
game.saveGame = () => true;
game.toast = () => {};
game.log = () => {};
game.sfx = () => {};
const state = game.state;
const gateIds = ['quarry', 'shrine', 'kiln', 'bamboo', 'ridge'];
const results = [];
for (let index = 0; index < STORY_CHAPTERS.length; index++) {
  state.story.chapter = index;
  results.push({ chapter: index + 1, gates: gateIds.map(id => locationStoryAccess(state, id).unlocked) });
  const chapter = STORY_CHAPTERS[index];
  for (const id of chapter.missions) {
    const mission = MISSIONS.find(item => item.id === id);
    const goal = mission.goal;
    if (goal.type === 'stat') state.stats[goal.key] = goal.need;
    if (goal.type === 'gathered') state.stats[`gathered_${goal.key}`] = goal.need;
    if (goal.type === 'material') state.materials[goal.key] = goal.need;
    if (goal.type === 'rep') state.rep = goal.need;
    if (goal.type === 'masterpiece') state.stats.masterpieceSold = 1;
    if (goal.type === 'heirloom') state.trees[0].heirloom = true;
  }
  game.checkStory();
  if (state.story.chapter !== index + 1) throw new Error(`Chapter ${chapter.id} failed to advance: ${state.story.chapter}`);
  const moneyAfterFirstCheck = state.money;
  game.checkStory();
  if (state.money !== moneyAfterFirstCheck) throw new Error(`Repeated check paid rewards again in ${chapter.id}`);
}
if (state.story.chapter !== STORY_CHAPTERS.length) throw new Error('Final story state incorrect');
console.log(JSON.stringify({ results, chaptersDone: state.story.chaptersDone, missionCount: state.story.done.length, storyComplete: state.story.chapter === STORY_CHAPTERS.length }, null, 2));
EOF

