node --input-type=module <<'EOF'
globalThis.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };
const { Game } = await import('./src/game.js');
const { World } = await import('./src/world.js');
const { LiteWorld } = await import('./src/world2d.js');
const { STORY_CHAPTERS } = await import('./src/data.js');

const game = new Game();
const notices = [];
game.toast = (text) => notices.push(text);
game.log = () => {};
game.sfx = () => {};
game.saveGame = () => true;
game.focus = () => {};

for (const [label, Klass, lite] of [['WebGL', World, false], ['2D', LiteWorld, true]]) {
  game.state.story.chapter = 3;
  const world = Object.create(Klass.prototype);
  world.game = game;
  world.player = lite
    ? { position: { x: 123, z: 456 } }
    : { position: { x: 123, z: 0, set(x, y, z) { this.x = x; this.y = y; this.z = z; } } };
  if (lite) {
    world.loc = { id: 'estate' };
    world.resize = () => {};
  } else {
    world.snapCamera = () => {};
    world.camYaw = 0;
    world.camPolar = 0;
    world.camDist = 0;
    world.currentZone = 'keep';
  }
  world.travelTo('ridge');
  if ((lite && world.loc.id !== 'estate') || (!lite && (world.player.position.x !== 123 || world.player.position.z !== 456))) {
    throw new Error(`${label}: locked direct travel mutated world state`);
  }
  if (!notices.at(-1)?.includes(STORY_CHAPTERS[4].title)) throw new Error(`${label}: missing locked-path prompt`);
  game.state.story.chapter = 4;
  world.travelTo('ridge');
  if (lite ? world.loc.id !== 'ridge' : world.player.position.x === 123) throw new Error(`${label}: unlocked ridge travel failed`);
  console.log(`${label} direct travel: locked route rejected, chapter V route accepted`);
}

game.state.story.chapter = 2;
game.state.money = 2400;
